use sgenaxis_work::document_edit::*;
fn content(label:&str)->DocumentContent{let (bytes,digest)=match label{"A"=>(r#"{"nodes":[{"id":"A"}],"refs":[]}"#,"sha256:f49210310bc7fe65341a1f376519a56a9edc62169e774945c879c68d1e869aae"),"B"=>(r#"{"nodes":[{"id":"B"}],"refs":[]}"#,"sha256:b26f60f1d61bab93fd61f8cfe4c062dde472299861f300da7cfb9a97f65d5295"),"C"=>(r#"{"nodes":[{"id":"C"}],"refs":[]}"#,"sha256:de3fa57e70f49fc823d7aa9f89c260956d5b37da37ac2408138acef872a18d59"),_=>panic!("bad probe fixture")};DocumentContent::from_parts(bytes.as_bytes().to_vec(),digest.into(),vec![],vec![],vec![])}

fn state()->DocumentSessionState{let a=content("A");DocumentSessionState{project_uuid:"11111111-1111-4111-8111-111111111111".into(),document_uuid:"22222222-2222-4222-8222-222222222222".into(),session_uuid:"33333333-3333-4333-8333-333333333333".into(),content_revision:Revision(0),formal_baseline:Some(SavedContentBaseline{revision:Revision(0),semantic_digest:a.semantic_digest().into()}),snapshot_baseline:Some(SavedContentBaseline{revision:Revision(0),semantic_digest:a.semantic_digest().into()}),content:a,status:SessionStatus::Editing,undo:vec![],redo:vec![]}}
#[test] fn repeated_edits_undo_to_original_without_restoring_old_revisions(){let initial=state();let mut s=DocumentSession::new(initial.clone());for i in 0..32{let after=content(if i%2==0{"B"}else{"C"});let p=s.prepare(Revision(i),MutationKind::Edit,after).unwrap();s.commit(p).unwrap();}assert_eq!(s.state().undo.len(),32);for i in 32..64{s.undo(Revision(i)).unwrap();}assert_eq!(s.state().content,initial.content);assert_eq!(s.state().content_revision,Revision(64));assert!(s.state().undo.is_empty());assert_eq!(s.state().redo.len(),32);assert_eq!(s.state().formal_baseline,initial.formal_baseline);assert_eq!(s.state().snapshot_baseline,initial.snapshot_baseline);}
#[test] fn replaying_plan_fails_without_second_mutation(){let mut s=DocumentSession::new(state());let plan=s.prepare(Revision(0),MutationKind::Merge,content("B")).unwrap();s.commit(plan.clone()).unwrap();let before=s.state().clone();assert_eq!(s.commit(plan),Err(EditError::RevisionConflict));assert_eq!(s.state(),&before);}
#[test] fn editing_after_undo_discards_only_redo(){let mut s=DocumentSession::new(state());let p=s.prepare(Revision(0),MutationKind::Edit,content("B")).unwrap();s.commit(p).unwrap();s.undo(Revision(1)).unwrap();assert_eq!(s.state().redo.len(),1);let p=s.prepare(Revision(2),MutationKind::Edit,content("C")).unwrap();s.commit(p).unwrap();assert!(s.state().redo.is_empty());assert_eq!(s.state().undo.len(),1);}
#[test] fn overflow_undo_retains_history_and_current_content(){let a=content("A");let b=content("B");let mut current=state();current.content=b.clone();current.content_revision=Revision(u64::MAX);current.undo.push(DocumentHistoryEntry{kind:MutationKind::Edit,before:a,after:b});let before=current.clone();let mut s=DocumentSession::new(current);assert_eq!(s.undo(Revision(u64::MAX)),Err(EditError::RevisionOverflow));assert_eq!(s.state(),&before);}
#[test] fn rejected_ack_keeps_both_baselines_and_history(){let mut s=DocumentSession::new(state());let before=s.state().clone();assert!(matches!(s.acknowledge_formal_save(Revision(0),"not-a-digest"),Err(EditError::InvalidInput{..})));assert!(matches!(s.acknowledge_recovery_save(Revision(0),"not-a-digest"),Err(EditError::InvalidInput{..})));assert_eq!(s.state(),&before);}
#[test] fn returned_capture_is_not_a_mutable_alias(){let mut s=DocumentSession::new(state());let capture=s.capture().unwrap();let p=s.prepare(Revision(0),MutationKind::Edit,content("B")).unwrap();s.commit(p).unwrap();assert_eq!(capture.content,content("A"));assert_eq!(capture.revision,Revision(0));assert_ne!(capture.content,s.state().content);}
#[test] fn all_blocked_statuses_preserve_state_on_every_mutation(){for status in [SessionStatus::Applying,SessionStatus::RecoveryRequired,SessionStatus::Closed]{let mut initial=state();initial.status=status;let mut s=DocumentSession::new(initial.clone());assert!(s.prepare(Revision(0),MutationKind::Clear,content("B")).is_err());assert!(s.undo(Revision(0)).is_err());assert!(s.capture().is_err());assert!(s.acknowledge_formal_save(Revision(0),content("A").semantic_digest()).is_err());assert!(s.acknowledge_recovery_save(Revision(0),content("A").semantic_digest()).is_err());assert_eq!(s.state(),&initial);}}
